// Generates src/generated/messages.js from schema/messages.json.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";

const root = new URL("../", import.meta.url);
const messages = JSON.parse(readFileSync(new URL("schema/messages.json", root), "utf8"));
const lines = [
  "// GENERATED by scripts/gen.mjs from schema/messages.json. Do not edit: change the schema and run `node scripts/gen.mjs`.",
  "export const messages = {",
  ...Object.entries(messages).map(([code, text]) => `  ${code}: ${JSON.stringify(text)},`),
  "};",
  "",
];
mkdirSync(new URL("src/generated/", root), { recursive: true });
writeFileSync(new URL("src/generated/messages.js", root), lines.join("\n"));
console.log("wrote src/generated/messages.js");
